import java.util.*;

class Solution {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String entrada = in.nextLine();
        String[] placas = entrada.split(",");

        final int ultimoIndice = 7;
        final int indexHifen = 3;

