		if(getNumberOfEdges() != getNumberOfVertices()-1) {
		  return false;
		}

    dfs(0, -1); // dfs no 0, -1 porque nao tem nenhum antecessor
    return this.reachableFromZero == getNumberOfVertices() && !this.hasCycle;
  }

