        System.out.print("listaDeAdjacencia[" + i + "] ->");

        for (Edge edge : list) {
            System.out.print(" (" + edge.getEndNode() + ", " + edge.getWeight() + ")");
        }

        i++;
        System.out.println();
    }
  }
}

