		for (int i = 0; i < aux.length; i++) {
			aux[i] = 0;
		}

		for (int i = 0; i < seq.length; i++) {
			if(aux[seq[i]-1] == 1) {
				return true;
			}
			aux[seq[i]]++;
		}
		return false;
	}

	private static int max(int[] seq) {
		int max = Integer.MIN_VALUE;

		for (int i = 0; i < seq.length; i++) {
			if(seq[i] > max) {
				max = seq[i];
			}
		}
		return max;
