1. **Implementar a BST**: Criar uma estrutura de dados para a BST que permita adicionar elementos e percorrer a árvore em pré-ordem.
2. **Percorrer a BST em pré-ordem**: Imprimir os elementos da BST em pré-ordem.
3. **Contar elementos menores que N**: Percorrer a BST e contar quantos elementos são menores que N.

Aqui está um exemplo de implementação em Java:

```java
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

class Node {
    int value;
    Node left, right;

    Node(int value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }
}

class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    public boolean isEmpty() {
        return this.root == null;
    }

    public void add(int value) {
        if (isEmpty()) {
            this.root = new Node(value);
        } else {
            this.root.add(value);
        }
    }

    public void preOrder(ArrayList<Integer> list) {
        if (root != null) {
            this.root.preOrder(list);
        }
    }

    public int countLessThan(int value, Node node) {
        if (node == null) {
            return 0;
        }
        if (node.value < value) {
            return 1 + countLessThan(value, node.left) + countLessThan(value, node.right);
        } else {
            return countLessThan(value, node.left);
        }
    }

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String input = scan.nextLine();

        String[] strArray = input.split(" ");
        int[] intArray = new int[strArray.length];
        for (int i = 0; i < strArray.length; i++) {
            intArray[i] = Integer.parseInt(strArray[i]);
        }

        BST tree = new BST();
        for (int i : intArray) {
            tree.add(i);
        }

        int N = Integer.parseInt(scan.nextLine());

        ArrayList<Integer> list = new ArrayList<>();
        tree.preOrder(list);
        System.out.println(Arrays.toString(list.toArray()));

        int count = tree.countLessThan(N, tree.root);
        System.out.println(count);
    }
}

class Node {
    int value;
    Node left, right;

    Node(int value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }

    public void preOrder(ArrayList<Integer> list) {
        list.add(this.value);
        if (this.left != null) {
            this.left.preOrder(list);
        }
        if (this.right != null) {
            this.right.preOrder(list);
        }
    }

    public void add(int value) {
        if (value < this.value) {
            if (this.left == null) {
                this.left = new Node(value);
            } else {
                this.left.add(value);
            }
        } else if (value > this.value) {
            if (this.right == null) {
                this.right = new Node(value);
            } else {
                this.right.add(value);
            }
        }
    }
}
```

